const driveFile = $('Google Drive - Nouveau fichier audio').first().json;
const nomFichier = driveFile.name || 'enregistrement';
const dossierClient = nomFichier
  .replace(/\.(m4a|mp3|wav|aac|ogg|opus|mp4|webm)$/i, '')
  .replace(/[_-]+/g, ' ')
  .trim();

return [{
  binary: $input.first().binary,
  json: {
    nom_fichier: nomFichier,
    dossier_client: dossierClient,
    fichier_drive_id: driveFile.id,
    date_enregistrement: new Date().toISOString().slice(0, 10),
    langue_code: 'fr',
    langue_sortie: 'Francais',
    niveau_masquage: 'Strict',
    email_secretariat: 'cabpgueu@gmail.com',
    email_destinataires_finaux: 'REMPLACER_PAR_EMAILS_PARTIES',
    session_id: `gueu_cr_${Date.now()}`,
    timestamp: new Date().toISOString()
  }
}];

const resp = $input.first().json;
const segments = resp.segments || [];
return Promise.all(segments.map(async (seg, idx) => ({
  json: { index: idx + 1, filename: seg.filename || `segment_${idx + 1}.mp3` },
  binary: { data: await this.helpers.prepareBinaryData(Buffer.from(seg.data_base64, 'base64'), seg.filename || `segment_${idx + 1}.mp3`, 'audio/mpeg') }
})));

const items = $input.all();
const meta = $('Preparer metadonnees dossier').first().json;
const parts = [];
for (let i = 0; i < items.length; i++) {
  const row = items[i].json || {};
  const text = (row.text || '').trim();
  if (text) parts.push(`Segment ${i + 1}\n${text}`);
}
return [{ json: { ...meta, transcription_brute: parts.join('\n\n'), nb_segments: parts.length } }];

const src = $input.first().json;
const table = {};
const counters = { PARTY: 1, EMAIL: 1, PHONE: 1, URL: 1, ID: 1 };
const nextToken = (prefix) => `${prefix}_${String(counters[prefix]++).padStart(3, '0')}`;
const esc = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const addMapping = (prefix, raw) => {
  const clean = (raw || '').trim();
  if (!clean) return null;
  const existing = Object.entries(table).find(([, value]) => value.toLowerCase() === clean.toLowerCase());
  if (existing) return existing[0];
  const token = nextToken(prefix);
  table[token] = clean;
  return token;
};

let transcript = src.transcription_brute || '';
let dossier = src.dossier_client || '';

const candidateEntities = [dossier, 'Cabinet GUEU', 'Maitre GUEU'].filter(Boolean).sort((a, b) => b.length - a.length);
for (const entity of candidateEntities) {
  const token = addMapping('PARTY', entity);
  if (!token) continue;
  transcript = transcript.replace(new RegExp(`\\b${esc(entity)}\\b`, 'gi'), token);
  dossier = dossier.replace(new RegExp(`\\b${esc(entity)}\\b`, 'gi'), token);
}

transcript = transcript.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, (match) => addMapping('EMAIL', match));
transcript = transcript.replace(/\+?\d[\d\s().-]{7,}\d/g, (match) => addMapping('PHONE', match));
transcript = transcript.replace(/https?:\/\/[^\s]+/gi, (match) => addMapping('URL', match));
transcript = transcript.replace(/\b[A-Z0-9_-]{8,}\b/g, (match) => addMapping('ID', match));

return [{ json: {
  ...src,
  sensitive_table: table,
  pii_count: Object.keys(table).length,
  dossier_pseudonymise: dossier,
  transcription_pseudonymisee: transcript
} }];

