const response = $input.first().json;
const prev = $('Pseudonymiser localement').first().json;
let raw = '';
for (const item of response.output || []) {
  if (item.type !== 'message') continue;
  for (const content of item.content || []) {
    if (content.type === 'output_text' && content.text) {
      raw = content.text;
      break;
    }
  }
  if (raw) break;
}
if (!raw && response.output_text) raw = response.output_text;
const parsed = JSON.parse(raw || '{}');
return [{ json: { ...prev, llm_raw: raw, llm_parsed: parsed } }];

const src = $input.first().json;
const map = src.sensitive_table || {};
let noteInterneClaire = src.llm_parsed.note_interne_markdown || '';
for (const [token, value] of Object.entries(map).sort((a, b) => b[0].length - a[0].length)) {
  noteInterneClaire = noteInterneClaire.replaceAll(token, value);
}
return [{ json: { ...src, note_interne_claire: noteInterneClaire } }];

const src = $input.first().json;
const store = $getWorkflowStaticData('global');
const sid = src.session_id;
const llm = src.llm_parsed || {};
const esc = (value) => String(value || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const block = (title, content) => `<div style="margin:18px 0"><h3 style="margin-bottom:8px;color:#0a3161">${esc(title)}</h3><pre style="white-space:pre-wrap;background:#f8f9ff;border:1px solid #dde;padding:16px;border-radius:8px;font-family:Menlo,monospace;font-size:12px;line-height:1.65">${esc(content)}</pre></div>`;
const previewHtml = `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><title>Validation juridique</title></head><body style="font-family:Georgia,serif;max-width:920px;margin:auto;padding:28px;color:#1a1a2e">
  <div style="border-top:4px solid #0a3161;padding-top:16px">
    <h1 style="margin:0">CABINET GUEU - Validation d'un compte rendu sensible</h1>
    <p style="color:#5c677d">Session ${esc(sid)} | Dossier ${esc(src.dossier_client)} | ${esc(src.date_enregistrement)}</p>
  </div>
  <div style="background:#fff8e6;border:1px solid #f4b400;padding:16px;border-radius:10px;margin-top:18px">
    <strong>Confidentialite :</strong> ${esc(src.pii_count)} donnees sensibles masquees avant traitement OpenAI. La diffusion finale reste sanitisee.
  </div>
  ${block('Email client sanitise', llm.email_client_corps || '')}
  ${block('Compte rendu client sanitise', llm.rapport_client_markdown || '')}
  ${block('Note interne reidentifiee - usage interne uniquement', src.note_interne_claire || '')}
  <div style="margin-top:24px;padding:18px;border-top:1px solid #dde">
    <a href="https://n8n-pxlk.srv1480638.hstgr.cloud/webhook/gueu-cr-approve?sid=${encodeURIComponent(sid)}" style="display:inline-block;padding:12px 18px;background:#1f8f4e;color:white;text-decoration:none;border-radius:8px;margin-right:8px">Valider et envoyer</a>
    <a href="https://n8n-pxlk.srv1480638.hstgr.cloud/webhook/gueu-cr-reject?sid=${encodeURIComponent(sid)}" style="display:inline-block;padding:12px 18px;background:#c0392b;color:white;text-decoration:none;border-radius:8px">Rejeter</a>
  </div>
</body></html>`;

const finalHtml = `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><title>${esc(llm.titre_sanitise || sid)}</title></head><body style="font-family:Georgia,serif;max-width:860px;margin:auto;padding:28px;color:#1a1a2e">${block('Email client sanitise', llm.email_client_corps || '')}${block('Compte rendu client sanitise', llm.rapport_client_markdown || '')}</body></html>`;
const archiveHtml = `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><title>${esc(llm.titre_sanitise || sid)}</title></head><body style="font-family:Georgia,serif;max-width:860px;margin:auto;padding:28px;color:#1a1a2e">${block('Compte rendu client sanitise', llm.rapport_client_markdown || '')}</body></html>`;

store[sid] = {
  preview_html: previewHtml,
  final_html: finalHtml,
  archive_html: archiveHtml,
  final_subject: llm.email_client_sujet || `Compte rendu de reunion - ${sid}`,
  email_destinataires_finaux: src.email_destinataires_finaux,
  email_secretariat: src.email_secretariat,
  dossier_client: src.dossier_client
};

return [{ json: {
  session_id: sid,
  preview_html: previewHtml,
  final_html: finalHtml,
  archive_html: archiveHtml,
  final_subject: llm.email_client_sujet || `Compte rendu de reunion - ${sid}`,
  email_secretariat: src.email_secretariat,
  email_destinataires_finaux: src.email_destinataires_finaux,
  dossier_client: src.dossier_client
} }];

const sid = $json.query?.sid || $json.sid || '';
if (!sid) throw new Error('Session ID manquant');
const store = $getWorkflowStaticData('global');
const data = store[sid];
if (!data) throw new Error(`Aucune session trouvee pour ${sid}`);
return [{ json: { sid, ...data } }];

const data = $input.first().json;
const fileName = `gueu_sanitized_report_${data.sid}.html`;
const binary = await this.helpers.prepareBinaryData(Buffer.from(data.archive_html || data.final_html || '<p>Archive vide</p>', 'utf8'), fileName, 'text/html');
return [{ json: { ...data, archive_file_name: fileName }, binary: { data: binary } }];
